def main():
    TEXT[91][2]='这敌人……'
    TEXT[94][1]='这点事我也能！'
    TEXT[99][0]='防御壁，展开！'
    TEXT[114][0]='啊，荒垣前辈！\n怎么会…怎么会这样……'
    TEXT[121][0]='啊，善，玲！\n怎么会…怎么会这样……！'
    TEXT[122][0]='啊，善！\n怎么会…怎么会这样……！'
    TEXT[137][0]='刚才是“发誓不动手打人”\n吗？'
    TEXT[139][0]='说了“发誓不使用道具”\n呢……'
    TEXT[149][0]='这、这似乎是这这里的，\n头、头目……'
    target=ROOT/'translation/batches/422_fuuka_completion.generated.json';assert not target.exists()
    sources=defaultdict(list);battle=0;named=0
    for r in read(ROOT/'translation/catalog.working.json'):
        if r.get('translation'):continue
        s=r['source'];i=r['message_index'];j=r['line_index'];old=r['original'];body=None
        if s.startswith('export_base/battle/support/bsv108.'):
            if 'ダミー' in old:continue
            m=int(re.search(r'_\((\d+)\)',s)[1]);assert j==0
            body=(COUNT[i] if m==181 else TEXT[m][i])+'\n';battle+=1
        elif any(t in str(r.get('speaker')) for t in ('風花','风花')):
            plain=TOKEN.sub('',old)
            if plain.strip()=='リザーブ':continue
            if s=='export_base/facility/msg_town.bmd.json':
                if i in (2,6) and j==0:body='队长，队伍里有人\n没有装备“副”人格面具。\n请注意。\n'
                elif i==4:body='没有携带，\n没关系吗？\n'
                else:
                    assert (i,j)==(6,1)
                    body='另外，没有携带{F4 84 04 01 01 01 36 06}，\n没关系吗？\n'
            else:
                assert plain=='リーダー、その扉の向こう側に敵が居ます。\n気を付けてください。\n'
                body='队长，那扇门后面有敌人。\n请小心。\n'
            named+=1
        if body is None:continue
        full=LEADING.match(old).group()+body+TRAILING.search(old).group()
        assert TOKEN.findall(full)==TOKEN.findall(old),r['key']
        a=TOKEN.sub('',old).splitlines();b=TOKEN.sub('',full).splitlines()
        assert len(b)<=len(a) and max(map(len,b))<=max(map(len,a)),(s,i,j,a,b)
        sources[s].append([i,j,read(ROOT/s)['texts'][i]['id'],body])
    assert (battle,named)==(165,6),(battle,named)
    write(target,dict(status='draft',sources=dict(sources),source_hashes={s:hashlib.sha256((ROOT/s).read_bytes()).hexdigest() for s in sources},review_notes=['风花剩余有效战斗165页及具名遗漏6页。神谕/克洛诺斯/誓言沿用既有术语；动态道具控制码保留。','探索脚本及副本已有译稿；占位及预留保持原样。目录范围完成不代表未提取或无标签文本全部查明；未运行验证。']))
    print('Fuuka battle completion:',battle,'named omissions:',named)

if __name__=='__main__':main()
